function mik(x){return x.dk?f(x.a,x.a%1?2:0)+" ton dökme":f(x.a,0)+" çuval"}
function fk(v){v=Math.round((+v||0)*100)/100;return f(v,v%1?2:0)}
function bfy(x){return x.dk?tl(x.p)+"/ton":fk(x.p)+" TL"}
function topMik(g){var L=[];if(g.cuv)L.push(f(g.cuv,0)+" çuval");if(g.dton)L.push(f(g.dton,g.dton%1?2:0)+" ton dökme");return L.join(" + ")+" ("+f(g.ton,g.ton%1?2:0)+" ton)"}
function degisti(o){o.mod=new Date().toISOString();var h=hesap(o);o.k.forEach(function(x){var g=h.G.filter(function(g){return g.F.id===x.f})[0],u=g&&uBul(g.F,x.ad);if(u){x.bf=fyB(o,g.F.id,u)||x.bf;x.fad=g.F.ad}});o.top=h.T.top;o.cuv=h.T.cuv;try{save()}catch(e){}}
function adet(o,fid,ad,a,dk){dk=!!dk;a=Math.max(0,dk?Math.round(num(a)*100)/100:Math.round(num(a)));var x=o.k.filter(function(x){return x.f===fid&&x.ad===ad&&!!x.dk===dk})[0];if(!x){if(!a)return;x={f:fid,ad:ad,a:0};if(dk)x.dk=true;o.k.push(x)}x.a=a;if(!a)o.k.splice(o.k.indexOf(x),1);degisti(o)}
window.spAdet=function(fid,ad,a,dk){var o=cur()||yeni();adet(o,fid,ad,a,dk)};
/* WhatsApp / paylaşım metni (firma başına) */
var NKOD={bayi:"bayi ödeyecek",firma:"fabrika ödeyecek"};
