 L.push("Sipariş no: "+o.no+(g.rev?" (revize)":"")+" · "+trT(o.t||bugun()));L.push("Ödeme: "+odAd(o,fid));if(g.F.tarih&&fyGoster)L.push("Fiyat listesi: "+trT(g.F.tarih));L.push("");
