/* önceki liste: her firma/tür için son görülen liste saklanır; liste tarihi değişince eskisi "önceki" olur, fiyatların yanında % değişim yazılır */
function oncekiL(key,L){var s=SP();s.lg=s.lg&&typeof s.lg==="object"?s.lg:{};var k=s.lg[key]=s.lg[key]&&typeof s.lg[key]==="object"?s.lg[key]:{};var snap=function(){return {tarih:L.tarih||"",u:L.u.map(function(u){var r={ad:u.ad,n:u.n,k:u.k};if(Array.isArray(u.f))r.f=u.f.slice();return r})}};
 if(!k.son){k.son=snap();save()}else if(k.son.tarih!==(L.tarih||"")){if((L.tarih||"")>k.son.tarih)k.once=k.son;k.son=snap();save()}else if(JSON.stringify(k.son.u)!==JSON.stringify(snap().u)){k.son=snap();save()}
 return k.once&&k.once.tarih<(L.tarih||"")?k.once:null}
window.spOnceki=oncekiL;
function degY(eski,yeni){if(!(eski>0)||!(yeni>0))return '';var tl=SP().degT==="tl",d=Math.round((yeni-eski)*100)/100,v=(yeni/eski-1)*100;if(Math.abs(d)<0.005)return '<br><small style="color:var(--mu)">'+(tl?'0 TL':'0%')+'</small>';return '<br><small style="color:'+(d>0?'var(--bad)':'var(--ok)')+';font-weight:600">'+(d>0?'+':'−')+(tl?f(Math.abs(d),Math.abs(d)%1?2:0)+' TL':f(Math.abs(v),1)+'%')+'</small>'}
