var PER_ISK={basaran:13,yemcibey:8};
function perAyar(fid){var s=SP();fid=fid||"basaran";s.perF=s.perF&&typeof s.perF==="object"?s.perF:{};var r=s.perF[fid];if(!r||typeof r!=="object"){r=s.perF[fid]={perIsk:PER_ISK[fid]!=null?PER_ISK[fid]:13,perDk:10};if(fid==="basaran"&&s.perIsk>=0){r.perIsk=s.perIsk;if(s.perDk>=0)r.perDk=s.perDk}}if(!(r.perIsk>=0))r.perIsk=PER_ISK[fid]!=null?PER_ISK[fid]:13;if(!(r.perDk>=0))r.perDk=10;return r}
