function sayiOku(t){t=String(t||"").trim().replace(/\s/g,"");if(t.indexOf(",")>=0)t=t.replace(/\./g,"").replace(",",".");else if(/\.\d{3}$/.test(t))t=t.replace(/\./g,"");return parseFloat(t)||0}
